<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/ConsequencePropagationService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once __DIR__.'/SimulationHarness.php';
$args=$argv;array_shift($args);
$opt=['plot'=>'EMPTY_THRONE','runs'=>10,'strategy'=>'no-action','duration'=>300,'step'=>30,'reset'=>false,'json'=>false,'npc-reasoner'=>'weighted','ai-npc-role'=>''];
$usage="Usage: php tools/simulate.php [options]\n"
    ."  --plot=CODE             Active plot code\n"
    ."  --runs=N               Number of simulations (default 10)\n"
    ."  --strategy=NAME        no-action, random, first, anti-rowan, pro-rowan\n"
    ."  --duration=SECONDS     Simulation duration (default 300)\n"
    ."  --step=SECONDS         Clock step (default 30)\n"
    ."  --npc-reasoner=NAME    weighted or ollama\n"
    ."  --ai-npc-role=CODE     Optional NPC role routed to the AI reasoner\n"
    ."  --json                 Print JSON output\n"
    ."  --reset                Test-database reset only\n"
    ."  --help, -h             Show this help without running simulations\n";
foreach($args as $a){
    if($a==='--help'||$a==='-h'){echo $usage;exit(0);}
    if($a==='--reset'){$opt['reset']=true;continue;}
    if($a==='--json'){$opt['json']=true;continue;}
    if(!preg_match('/^--([^=]+)=(.*)$/',$a,$m)){fwrite(STDERR,"Unknown argument: {$a}\n\n".$usage);exit(2);}
    $k=$m[1];$v=$m[2];
    if(!array_key_exists($k,$opt)){fwrite(STDERR,"Unknown option: --{$k}\n\n".$usage);exit(2);}
    $opt[$k]=in_array($k,['runs','duration','step'],true)?(int)$v:$v;
}
$strategies=['no-action','random','first','anti-rowan','pro-rowan'];if(!in_array($opt['strategy'],$strategies,true)){fwrite(STDERR,'Strategy must be '.implode(', ',$strategies).".\n");exit(2);}if((int)$opt['runs']<1){fwrite(STDERR,"--runs must be at least 1.\n");exit(2);}if(!in_array(strtolower((string)$opt['npc-reasoner']),['weighted','ollama'],true)){fwrite(STDERR,"--npc-reasoner must be weighted or ollama.\n");exit(2);}
$dbOverride=trim((string)getenv('GAME2_DATABASE_CONFIG'));if($opt['reset']&&($dbOverride===''||!str_contains(basename($dbOverride),'test'))){fwrite(STDERR,"Refusing --reset unless GAME2_DATABASE_CONFIG explicitly points to a test database config.\n");exit(2);}
if(strtolower((string)$opt['npc-reasoner'])==='ollama'){putenv('GAME2_SIM_NPC_REASONER=ollama');putenv('GAME2_AI_PROVIDER=ollama');if(trim((string)$opt['ai-npc-role'])!=='')putenv('GAME2_SIM_AI_NPC_ROLE='.strtoupper(trim((string)$opt['ai-npc-role'])));}else{putenv('GAME2_SIM_NPC_REASONER=weighted');}
try{if($opt['reset'])SimulationHarness::resetDatabase();else MigrationService::run();$results=[];$outcomes=[];$familyLabels=[];$warningCount=0;$factorRanges=[];$totals=['player_actions'=>0,'npc_actions'=>0,'player_no_action'=>0];$aiTotals=['calls'=>0,'successes'=>0,'failures'=>0,'prompt_tokens'=>0,'generated_tokens'=>0,'total_tokens'=>0,'latency_ms'=>0.0,'ollama_total_ms'=>0.0];for($i=1;$i<=(int)$opt['runs'];$i++){$r=SimulationHarness::run((string)$opt['plot'],(string)$opt['strategy'],(int)$opt['duration'],(int)$opt['step']);$results[]=$r;$label=(string)$r['outcome_family_label'];$sig=substr(hash('sha256',$label),0,12);$outcomes[$sig]=($outcomes[$sig]??0)+1;$familyLabels[$sig]=$label;$warningCount+=count($r['warnings']);foreach($r['counts']as$k=>$v)$totals[$k]+=$v;foreach($r['ai_usage']as$k=>$v)$aiTotals[$k]+=$v;foreach($r['factors']as$k=>$v){if(!isset($factorRanges[$k]))$factorRanges[$k]=['min'=>$v,'max'=>$v];else{$factorRanges[$k]['min']=min($factorRanges[$k]['min'],$v);$factorRanges[$k]['max']=max($factorRanges[$k]['max'],$v);}}}arsort($outcomes);$families=[];foreach($outcomes as$sig=>$n)$families[]=['signature'=>$sig,'count'=>$n,'percent'=>round($n*100/(int)$opt['runs'],1),'label'=>$familyLabels[$sig]];$summary=['plot'=>$opt['plot'],'runs'=>(int)$opt['runs'],'strategy'=>$opt['strategy'],'npc_reasoner'=>$opt['npc-reasoner'],'ai_npc_role'=>$opt['ai-npc-role']?:null,'unique_outcome_families'=>count($outcomes),'outcome_families'=>$families,'average_counts'=>array_map(fn($v)=>round($v/(int)$opt['runs'],2),$totals),'ai_usage_total'=>['calls'=>(int)$aiTotals['calls'],'successes'=>(int)$aiTotals['successes'],'failures'=>(int)$aiTotals['failures'],'prompt_tokens'=>(int)$aiTotals['prompt_tokens'],'generated_tokens'=>(int)$aiTotals['generated_tokens'],'total_tokens'=>(int)$aiTotals['total_tokens'],'latency_ms'=>round((float)$aiTotals['latency_ms'],2),'ollama_total_ms'=>round((float)$aiTotals['ollama_total_ms'],2)],'ai_usage_average_per_run'=>['calls'=>round($aiTotals['calls']/(int)$opt['runs'],2),'tokens'=>round($aiTotals['total_tokens']/(int)$opt['runs'],2),'latency_ms'=>round($aiTotals['latency_ms']/(int)$opt['runs'],2)],'factor_ranges'=>$factorRanges,'warning_count'=>$warningCount,'runs_detail'=>$results];if($opt['json']){echo json_encode($summary,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;exit($warningCount?1:0);}echo "Game2 simulation batch\nPlot: {$opt['plot']} | Runs: {$opt['runs']} | Strategy: {$opt['strategy']} | NPC reasoner: {$opt['npc-reasoner']}".($opt['ai-npc-role']?' | AI NPC: '.$opt['ai-npc-role']:'')."\nSemantic outcome families: ".count($outcomes)."\n";foreach(array_slice($families,0,15)as$f)echo '  '.$f['count'].' ('.$f['percent'].'%) '.$f['label'].PHP_EOL;echo "Average player actions: {$summary['average_counts']['player_actions']}\nAverage NPC actions: {$summary['average_counts']['npc_actions']}\nAverage player no-actions: {$summary['average_counts']['player_no_action']}\n";if($aiTotals['calls']>0)echo "AI calls: {$aiTotals['calls']} | Successes: {$aiTotals['successes']} | Failures: {$aiTotals['failures']} | Tokens: {$aiTotals['total_tokens']} | AI latency: ".round($aiTotals['latency_ms']/1000,2)."s\n";echo "Factor ranges:\n";foreach($factorRanges as$k=>$range)echo "  {$k}: {$range['min']}..{$range['max']}\n";echo "Integrity warnings: {$warningCount}\n";if($warningCount)foreach($results as$r)foreach($r['warnings']as$w)echo "  Simulation {$r['simulation_id']}: {$w}\n";exit($warningCount?1:0);}catch(Throwable$e){fwrite(STDERR,'Simulation harness failed: '.$e->getMessage().PHP_EOL);exit(1);}
